  "focus": "Rack-app (retrieval-augmented generation) and end-Agentic project",
  "modules": [
    {
      "module_title": "1. Overview: What is Rack?",
      "objectives": [
        "Discuss what Rack is and the components of Rack and how they are arranged",
        "Clarify scope: not covering which problems Rack solves (refer to advanced Rack course for that)"
      ]
    },
    {
      "module_title": "2. Project Start & Structure",
      "objectives": [
        "How to start a project and instantiate it",
        "Identify the starting point of your project",
        "Project organization: how to keep it as a container and initial steps to take"
      ]
    },
    {
      "module_title": "3. Rack Chatbot Plan",
      "objectives": [
        "Introduce the basic Rack Chatbot we will build (transcript-focused)",
        "High-level flow of the Rack application: retrieval, augmentation, generation"
      ]
    },
    {
      "module_title": "4. Transcript Pipeline: Cleaning and Storage",
      "objectives": [
        "Collect transcripts (live course Zoom transcripts)",
        "Clean transcripts (identify and address issues in the raw transcripts)",
        "Store cleaned transcripts in one place"
      ]
    },
    {
      "module_title": "5. Loading, Chunking, and Vectorization",
      "objectives": [
        "Load stored transcripts",
        "Chunkify transcripts into manageable chunks",
        "Load chunks into a vector store"
      ]
    },
    {
      "module_title": "6. Retrieval: Querying the Vector Store",
      "objectives": [
        "Query the vector store",
        "Perform a similarity search operation",
        "Retrieve relevant context from the vector store"
      ]
    },
    {
      "module_title": "7. Prompting and Generation",
      "objectives": [
        "Create a prompt using the retrieved context and the user query",
        "Generate the response by giving the prompt+context to the LLM",
        "Understand the three RAG steps covered: retrieval, augmentation, generation"
      ]
    },
    {
      "module_title": "8. Building the Full Rack App",
      "objectives": [
        "Assemble the full flow while building the Rack application (end-to-end)",
        "Instantiate the project and tie together transcript pipeline, vector store, retrieval, prompting, and generation"
      ]
    },
    {
      "module_title": "9. Capstone: End-Agentic Project",
      "objectives": [
        "Apply learned Rack-app concepts to an agentic-style project (end project)",
        "Integrate retrieval, augmentation, and generation into an agentic/advanced Rack application"
      ]
    },
    {
      "module_title": "10. Wrap-up and Q&A",
      "objectives": [
        "Short Q&A session (five minutes) to address student questions",
        "Recommend advanced courses for deeper coverage of Rack and RAG concepts"
      ]
    }
  ]
}

